def quiz(sid, eyebrow, title, qs, notes):
    def f():
        hd, est = header(eyebrow, title, CO)
        blocks = []
        e = 0
        for n, q, opts in qs:
            ops = ''.join(f'<p style="font-size:24px;line-height:1.4;color:{TEXT};background:{CARD};border:1px solid {LINE};padding:7px 20px;border-radius:12px">{t(o)}</p>' for o in opts)
            blocks.append(f'<div style="display:flex;flex-direction:column;gap:10px">'
                          f'<div style="display:flex;flex-direction:row-reverse;align-items:center;gap:18px">{num_badge(n, CO, 44)}'
                          f'<p style="flex:1;font-size:28px;font-weight:600;line-height:1.4;color:{TEXT}">{t(q)}</p></div>'
                          f'<div style="display:flex;flex-direction:row-reverse;flex-wrap:wrap;gap:12px;padding-right:62px">{ops}</div></div>')
            e += max(44, th(q, 28, 1560, 1.4, 0.53)) + 10 + 24 * 1.4 + 16 + 2
        e += 20 * (len(qs) - 1)
        body = f'<div style="display:flex;flex-direction:column;gap:20px">{"".join(blocks)}</div>'
        return section(sid, hd + body, notes, comp=CO, foot=F, gap=36, budget_used=est + 36 + e)
    S.append(('raw', dict(id=sid, fn=f)))

