def exhibit(n, sid, title, fn, notes=''):
    S.append(('exhibit', dict(id=sid, comp=CO, eyebrow=f'اختبار الأداء · الدليل {n}', title=title, foot=F, media=dict(fn=fn),
        notes=('دليل اختبار ببيانات افتراضية لهيئة المدار، ونصه الكامل في ملف «أدلة الاختبار». لا تعلّق على الدليل أثناء الاختبار؛ الحل في ملف المدرب المنفصل. ' + notes).strip())))

