# ---------------------------------------------------------------- closing
def closing():
    green, yellow, grey = C['tp'][2], C['res'][2], '#6B7686'
    seq = [green] * 28
    seq[12] = yellow; seq[19] = yellow; seq[26] = grey
    sq = []
    for r in range(4):
        cells = ''.join(f'<div style="flex:1;background:{c};border-radius:8px"></div>' for c in seq[r * 7:(r + 1) * 7])
        sq.append(f'<div style="flex:1;display:flex;flex-direction:row-reverse;gap:12px">{cells}</div>')
    leg = ''.join(f'<div style="display:flex;flex-direction:row-reverse;align-items:center;gap:10px"><div style="width:18px;height:18px;border-radius:5px;background:{c}"></div>'
                  f'<p style="font-size:24px;line-height:1.4;color:{ON_SOFT}">{t(n)}</p></div>' for c, n in ((green, 'مطبق'), (yellow, 'قيد الاستكمال'), (grey, 'غير منطبق بمبرر')))
    motif = (f'<div style="position:absolute;left:128px;top:300px;width:560px;height:320px;display:flex;flex-direction:column;gap:12px">{"".join(sq)}</div>'
             f'<div style="position:absolute;left:128px;top:650px;width:560px;display:flex;flex-direction:row;gap:28px">{leg}</div>')
    tk = [('الأساس', 'حوكمة ومالكون وحصر للأصول قبل الأدوات.'), ('الطبقات', 'وثّق، وطبّق، وغطِّ الحد الأدنى، وراجع.'),
          ('الدليل', 'حديث، ويغطي المجتمع المعني أو عينة مبررة، ويُحكم عليه بحدوده.'), ('الاستدامة', 'تقويم مراجعات، ومؤشرات، وتقارير للجنة.')]
    items = ''.join(f'<div style="display:flex;flex-direction:row-reverse;align-items:center;gap:22px;border-top:1px solid {ON_LINE};padding-top:18px">'
                    f'{num_badge(i + 1, CO, 52, dark=True)}<div style="flex:1;display:flex;flex-direction:column;gap:2px">'
                    f'<h3 style="font-family:{H};font-size:34px;font-weight:700;line-height:1.3;color:{ON}">{t(a)}</h3>'
                    f'<p style="font-size:28px;line-height:1.45;color:{ON_SOFT}">{t(b)}</p></div></div>' for i, (a, b) in enumerate(tk))
    inner = (f'<div style="width:1000px;display:flex;flex-direction:column;gap:22px;align-self:flex-end">'
             f'<p style="font-size:26px;font-weight:600;line-height:1.4;color:{C["base"][2]}">{t("ختام الكورس")}</p>'
             f'<h1 style="font-family:{H};font-size:88px;font-weight:800;line-height:1.2;color:{ON}">{t("الخلاصة")}</h1>'
             f'<div style="display:flex;flex-direction:column;gap:18px">{items}</div></div>'
             f'{spacer()}'
             f'<p style="font-size:24px;line-height:1.5;color:{ON_SOFT};width:1000px;align-self:flex-end">{t("المرجع: الضوابط الأساسية للأمن السيبراني ECC-2:2024 الصادرة عن الهيئة الوطنية للأمن السيبراني. راجع nca.gov.sa لأحدث نسخة، والنص العربي هو المعتمد عند الاختلاف.")}</p>')
    notes = NOTE('closing').replace('التمرين 7', 'التمرين 8')
    return section('closing', motif + inner, notes, bg=INK, color=ON, stripe=False, gap=0, pad='128px', transition='fade')

S.append(('raw', dict(id='closing', fn=closing)))
